"use client";

import { localStorageUtil } from "@/lib/utils/localStorageUtil";

import { runtimeConfig } from "@/lib/utils/runtimeConfig";
import React, { useEffect, useState } from "react";
import modalStyles from "@/styles/Modal.module.scss";
import styles from "@/styles/BusinessUnits.module.scss";
import { FaRegEdit, FaTrashAlt } from "react-icons/fa";
import Swal from "sweetalert2";
import { fetchWithAuth } from "@/lib/utils/fetchWithAuth";

const API_BASE_URL = runtimeConfig.getApiUrl("administrative");

type Area = {
  areasId: number;
  areasName: string;
  areasDescription: string;
};

// Aligned with BusinessUnitsDTO.java
type BusinessUnit = {
  businessUnitsId?: number;
  businessUnitsCode: string; // Updated from description
  businessUnitsName: string;
  areasId: number;
};

export default function BusinessUnit() {
  const canAdd = localStorageUtil.canAdd("admin.businessUnits");
  const canEdit = localStorageUtil.canEdit("admin.businessUnits");
  const canDelete = localStorageUtil.canDelete("admin.businessUnits");
  const [areas, setAreas] = useState<Area[]>([]);
  const [businessUnits, setBusinessUnits] = useState<BusinessUnit[]>([]);

  // State variables aligned with your Java Entity field names
  const [buName, setBuName] = useState("");
  const [buCode, setBuCode] = useState("");
  const [selectedArea, setSelectedArea] = useState<number | "">("");

  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<number | null>(null);
  const [filterAreaId, setFilterAreaId] = useState<number | "">("");

  const handleClear = () => {
    setBuName("");
    setBuCode("");
    setSelectedArea("");
    setIsEditing(false);
    setEditId(null);
  };

  const loadAreas = async () => {
    const res = await fetchWithAuth(`${API_BASE_URL}/api/areas/get-all`, {
      method: "GET",
    });
    const data = await res.json();
    setAreas(data);
  };

  const loadBusinessUnits = async () => {
    const res = await fetchWithAuth(
      `${API_BASE_URL}/api/businessUnits/get-all`,
      { method: "GET" },
    );
    const data = await res.json();
    setBusinessUnits(data);
  };

  useEffect(() => {
    loadAreas();
    loadBusinessUnits();
  }, []);

  const onSubmit = async (e: React.FormEvent) => {
    /* RBAC:onSubmit */

    if (isEditing ? !canEdit : !canAdd) {
      e.preventDefault();

      void Swal.fire({
        icon: "warning",
        title: "Permission denied",
        text: isEditing
          ? "You do not have permission to edit this record."
          : "You do not have permission to add a record.",
      });

      return;
    }
    e.preventDefault();

    // This payload matches the structure of BusinessUnitsDTO.java
    const payload = {
      businessUnitsName: buName,
      businessUnitsCode: buCode,
      areasId: selectedArea,
    };

    try {
      const url = isEditing
        ? `${API_BASE_URL}/api/businessUnits/update/${editId}`
        : `${API_BASE_URL}/api/businessUnits/create`;

      const method = isEditing ? "PUT" : "POST";

      const res = await fetchWithAuth(url, {
        method: method,
        body: JSON.stringify(payload),
      });

      if (!res.ok) throw new Error();

      Swal.fire({
        toast: true,
        position: "bottom-end",
        icon: "success",
        title: isEditing ? "Updated Successfully" : "Created Successfully",
        timer: 2000,
        showConfirmButton: false,
      });

      loadBusinessUnits();
      handleClear();
    } catch {
      Swal.fire("Error", "Operation failed", "error");
    }
  };

  const handleDelete = async (id: number) => {
    /* RBAC:handleDelete */

    if (!canDelete) {
      void Swal.fire({
        icon: "warning",
        title: "Permission denied",
        text: "You do not have permission to delete this record.",
      });

      return;
    }
    const result = await Swal.fire({
      text: "Are you sure you want to delete this record?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonText: "Delete",
    });

    if (!result.isConfirmed) return;

    await fetchWithAuth(`${API_BASE_URL}/api/businessUnits/delete/${id}`, {
      method: "DELETE",
    });
    loadBusinessUnits();
  };

  const handleEdit = (bu: BusinessUnit) => {
    /* RBAC:handleEdit */

    if (!canEdit) {
      void Swal.fire({
        icon: "warning",
        title: "Permission denied",
        text: "You do not have permission to edit this record.",
      });

      return;
    }
    setIsEditing(true);
    setEditId(bu.businessUnitsId!);
    setBuName(bu.businessUnitsName);
    setBuCode(bu.businessUnitsCode);
    setSelectedArea(bu.areasId);
  };

  const getAreaName = (areaId: number) => {
    const area = areas.find((a) => a.areasId === areaId);
    return area ? area.areasName : "N/A";
  };

  return (
    <div className={modalStyles.Modal}>
      <div className={modalStyles.modalContent}>
        <div className={modalStyles.modalHeader}>
          <h2 className={modalStyles.mainTitle}>Business Units Management</h2>
        </div>

        <div className={modalStyles.modalBody}>
          <form className={styles.BusinessUnitsForm} onSubmit={onSubmit}>
            <label>Select Area</label>
            <select
              value={selectedArea}
              onChange={(e) => setSelectedArea(Number(e.target.value))}
              required
            >
              <option value="">Choose an Area</option>
              {areas.map((area) => (
                <option key={area.areasId} value={area.areasId}>
                  {area.areasName}
                </option>
              ))}
            </select>

            <label>Business Unit Code</label>
            <input
              type="text"
              value={buCode}
              onChange={(e) => setBuCode(e.target.value)}
              required
              placeholder="e.g. BU-2024"
            />

            <label>Business Unit Name</label>
            <input
              type="text"
              value={buName}
              onChange={(e) => setBuName(e.target.value)}
              required
              placeholder="Enter Name"
            />

            <div className={styles.buttonGroup}>
              <button
                type="submit"
                className={isEditing ? styles.updateButton : styles.saveButton}
                disabled={isEditing ? !canEdit : !canAdd}
              >
                {isEditing ? "Update" : "Save"}
              </button>
              <button
                type="button"
                className={styles.clearButton}
                onClick={handleClear}
              >
                Clear
              </button>
            </div>
          </form>

          {businessUnits.length > 0 && (
            <div className={styles.BusinessUnitsTable}>
              <div
                style={{
                  padding: "12px 16px",
                  borderBottom: "1px solid #e0e0e0",
                  display: "flex",
                  alignItems: "center",
                  gap: "12px",
                }}
              >
                <label style={{ fontWeight: "bold", whiteSpace: "nowrap" }}>
                  Filter by Area:
                </label>
                <select
                  value={filterAreaId}
                  onChange={(e) =>
                    setFilterAreaId(
                      e.target.value === "" ? "" : Number(e.target.value),
                    )
                  }
                  style={{
                    borderRadius: "4px",
                    border: "1px solid #ccc",
                    padding: "6px 10px",
                    minWidth: "220px",
                  }}
                >
                  <option value="">All Areas</option>
                  {areas.map((area) => (
                    <option key={area.areasId} value={area.areasId}>
                      {area.areasName}
                    </option>
                  ))}
                </select>
              </div>
              <table className={styles.table}>
                <thead>
                  <tr>
                    <th>Code</th>
                    <th>Name</th>
                    <th>Area</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {businessUnits
                    .filter(
                      (bu) =>
                        filterAreaId === "" || bu.areasId === filterAreaId,
                    )
                    .map((bu) => (
                      <tr key={bu.businessUnitsId}>
                        <td>{bu.businessUnitsCode}</td>
                        <td>{bu.businessUnitsName}</td>
                        <td>{getAreaName(bu.areasId)}</td>

                        <td>
                          <button
                            className={`${styles.iconButton} ${styles.editIcon}`}
                            onClick={() => handleEdit(bu)}
                          >
                            <FaRegEdit />
                          </button>
                          <button
                            className={`${styles.iconButton} ${styles.deleteIcon}`}
                            onClick={() => handleDelete(bu.businessUnitsId!)}
                          >
                            <FaTrashAlt />
                          </button>
                        </td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
